// ✅ D:\PythonProject3\src\DepositForm.jsx

import React, { useState } from "react";

function DepositForm({ token, onCancel }) {
  const [amount, setAmount] = useState("");
  const [method, setMethod] = useState("bKash");
  const [senderNumber, setSenderNumber] = useState("");
  const [transactionId, setTransactionId] = useState("");
  const [message, setMessage] = useState("");

  const handleSubmit = async (e) => {
    e.preventDefault();

    const payload = {
      amount: parseFloat(amount),
      method,
      senderNumber,
      transactionId,
    };

    try {
      const res = await fetch("http://localhost:8080/api/deposit/request", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
      });

      if (!res.ok) throw new Error("Deposit failed");

      setMessage("✅ ডিপোজিট রিকোয়েস্ট সফলভাবে পাঠানো হয়েছে!");
      setAmount("");
      setSenderNumber("");
      setTransactionId("");
    } catch (err) {
      console.error("Deposit error:", err);
      setMessage("❌ ডিপোজিট ব্যর্থ হয়েছে");
    }
  };

  return (
    <div style={{ padding: "20px", maxWidth: "500px", margin: "auto" }}>
      <h2>💰 ডিপোজিট ফর্ম</h2>

      {message && (
        <p style={{ fontWeight: "bold", color: message.startsWith("✅") ? "green" : "red" }}>
          {message}
        </p>
      )}

      <form onSubmit={handleSubmit}>
        <div>
          <label>Amount:</label>
          <input
            type="number"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            required
            style={{ width: "100%", marginBottom: "10px" }}
          />
        </div>

        <div>
          <label>Method:</label>
          <select
            value={method}
            onChange={(e) => setMethod(e.target.value)}
            style={{ width: "100%", marginBottom: "10px" }}
          >
            <option value="bKash">bKash</option>
            <option value="Nagad">Nagad</option>
            <option value="Rocket">Rocket</option>
          </select>
        </div>

        <div>
          <label>Sender Number:</label>
          <input
            type="text"
            value={senderNumber}
            onChange={(e) => setSenderNumber(e.target.value)}
            required
            style={{ width: "100%", marginBottom: "10px" }}
          />
        </div>

        <div>
          <label>Transaction ID:</label>
          <input
            type="text"
            value={transactionId}
            onChange={(e) => setTransactionId(e.target.value)}
            required
            style={{ width: "100%", marginBottom: "10px" }}
          />
        </div>

        <button type="submit" style={{ marginRight: "10px" }}>Submit</button>
        <button type="button" onClick={onCancel}>⬅️ ফিরে যান</button>
      </form>
    </div>
  );
}

export default DepositForm;
